-- Estructura (solo columnas y tipos) de los esquemas auth y storage de gmlbmyreoxgoqrolhyxo,
-- leida el 2026-11-19 desde pg_catalog (sin datos). Sirve para restaurar auth_storage.dump,
-- que es solo de datos: en una recuperacion real, Supabase crea estos esquemas en el proyecto nuevo.
-- Llaves primarias solo donde las necesita la prueba (auth.users, storage.buckets, storage.objects).
create schema if not exists auth;
create schema if not exists storage;
-- Única secuencia de auth y storage (el dump de datos restaura su valor con setval).
create sequence auth.refresh_tokens_id_seq;
create type auth.aal_level as enum ('aal1', 'aal2', 'aal3');
create type auth.code_challenge_method as enum ('s256', 'plain');
create type auth.factor_status as enum ('unverified', 'verified');
create type auth.factor_type as enum ('totp', 'webauthn', 'phone', 'recovery_code');
create type auth.oauth_authorization_status as enum ('pending', 'approved', 'denied', 'expired');
create type auth.oauth_client_type as enum ('public', 'confidential');
create type auth.oauth_registration_type as enum ('dynamic', 'manual');
create type auth.oauth_response_type as enum ('code');
create type auth.one_time_token_type as enum ('confirmation_token', 'reauthentication_token', 'recovery_token', 'email_change_token_new', 'email_change_token_current', 'phone_change_token');
create type storage.buckettype as enum ('STANDARD', 'ANALYTICS', 'VECTOR');
create table auth.audit_log_entries (instance_id uuid, id uuid, payload json, created_at timestamp with time zone, ip_address character varying(64));
create table auth.custom_oauth_providers (id uuid, provider_type text, identifier text, name text, client_id text, client_secret text, acceptable_client_ids text[], scopes text[], pkce_enabled boolean, attribute_mapping jsonb, authorization_params jsonb, enabled boolean, email_optional boolean, issuer text, discovery_url text, skip_nonce_check boolean, cached_discovery jsonb, discovery_cached_at timestamp with time zone, authorization_url text, token_url text, userinfo_url text, jwks_uri text, created_at timestamp with time zone, updated_at timestamp with time zone, custom_claims_allowlist text[]);
create table auth.flow_state (id uuid, user_id uuid, auth_code text, code_challenge_method auth.code_challenge_method, code_challenge text, provider_type text, provider_access_token text, provider_refresh_token text, created_at timestamp with time zone, updated_at timestamp with time zone, authentication_method text, auth_code_issued_at timestamp with time zone, invite_token text, referrer text, oauth_client_state_id uuid, linking_target_id uuid, email_optional boolean);
create table auth.identities (provider_id text, user_id uuid, identity_data jsonb, provider text, last_sign_in_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, email text, id uuid);
create table auth.instances (id uuid, uuid uuid, raw_base_config text, created_at timestamp with time zone, updated_at timestamp with time zone);
create table auth.mfa_amr_claims (session_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, authentication_method text, id uuid);
create table auth.mfa_challenges (id uuid, factor_id uuid, created_at timestamp with time zone, verified_at timestamp with time zone, ip_address inet, otp_code text, web_authn_session_data jsonb);
create table auth.mfa_factors (id uuid, user_id uuid, friendly_name text, factor_type auth.factor_type, status auth.factor_status, created_at timestamp with time zone, updated_at timestamp with time zone, secret text, phone text, last_challenged_at timestamp with time zone, web_authn_credential jsonb, web_authn_aaguid uuid, last_webauthn_challenge_data jsonb);
create table auth.mfa_recovery_code_sets (id uuid, user_id uuid, mfa_factor_id uuid, failed_verification_count integer, verification_locked_until timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone);
create table auth.mfa_recovery_codes (id uuid, mfa_recovery_code_set_id uuid, code_hash text, consumed_at timestamp with time zone, created_at timestamp with time zone);
create table auth.oauth_authorizations (id uuid, authorization_id text, client_id uuid, user_id uuid, redirect_uri text, scope text, state text, resource text, code_challenge text, code_challenge_method auth.code_challenge_method, response_type auth.oauth_response_type, status auth.oauth_authorization_status, authorization_code text, created_at timestamp with time zone, expires_at timestamp with time zone, approved_at timestamp with time zone, nonce text);
create table auth.oauth_client_states (id uuid, provider_type text, code_verifier text, created_at timestamp with time zone);
create table auth.oauth_clients (id uuid, client_secret_hash text, registration_type auth.oauth_registration_type, redirect_uris text, grant_types text, client_name text, client_uri text, logo_uri text, created_at timestamp with time zone, updated_at timestamp with time zone, deleted_at timestamp with time zone, client_type auth.oauth_client_type, token_endpoint_auth_method text);
create table auth.oauth_consents (id uuid, user_id uuid, client_id uuid, scopes text, granted_at timestamp with time zone, revoked_at timestamp with time zone);
create table auth.one_time_tokens (id uuid, user_id uuid, token_type auth.one_time_token_type, token_hash text, relates_to text, created_at timestamp without time zone, updated_at timestamp without time zone, expires_at timestamp with time zone, link_token_hash text);
create table auth.refresh_tokens (instance_id uuid, id bigint, token character varying(255), user_id character varying(255), revoked boolean, created_at timestamp with time zone, updated_at timestamp with time zone, parent character varying(255), session_id uuid);
create table auth.saml_providers (id uuid, sso_provider_id uuid, entity_id text, metadata_xml text, metadata_url text, attribute_mapping jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, name_id_format text, dedicated_scope boolean);
create table auth.saml_relay_states (id uuid, sso_provider_id uuid, request_id text, for_email text, redirect_to text, created_at timestamp with time zone, updated_at timestamp with time zone, flow_state_id uuid);
create table auth.schema_migrations (version character varying(255));
create table auth.scim_tokens (id uuid, sso_provider_id uuid, token_hash text, prefix text, created_at timestamp with time zone, expires_at timestamp with time zone, revoked_at timestamp with time zone, last_used_at timestamp with time zone);
create table auth.scim_users (id uuid, sso_provider_id uuid, user_id uuid, resource jsonb, user_name text, external_id text, active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, deleted_at timestamp with time zone);
create table auth.sessions (id uuid, user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, factor_id uuid, aal auth.aal_level, not_after timestamp with time zone, refreshed_at timestamp without time zone, user_agent text, ip inet, tag text, oauth_client_id uuid, refresh_token_hmac_key text, refresh_token_counter bigint, scopes text);
create table auth.sso_domains (id uuid, sso_provider_id uuid, domain text, created_at timestamp with time zone, updated_at timestamp with time zone);
create table auth.sso_providers (id uuid, resource_id text, created_at timestamp with time zone, updated_at timestamp with time zone, disabled boolean);
create table auth.users (instance_id uuid, id uuid primary key, aud character varying(255), role character varying(255), email character varying(255), encrypted_password character varying(255), email_confirmed_at timestamp with time zone, invited_at timestamp with time zone, confirmation_token character varying(255), confirmation_sent_at timestamp with time zone, recovery_token character varying(255), recovery_sent_at timestamp with time zone, email_change_token_new character varying(255), email_change character varying(255), email_change_sent_at timestamp with time zone, last_sign_in_at timestamp with time zone, raw_app_meta_data jsonb, raw_user_meta_data jsonb, is_super_admin boolean, created_at timestamp with time zone, updated_at timestamp with time zone, phone text, phone_confirmed_at timestamp with time zone, phone_change text, phone_change_token character varying(255), phone_change_sent_at timestamp with time zone, confirmed_at timestamp with time zone, email_change_token_current character varying(255), email_change_confirm_status smallint, banned_until timestamp with time zone, reauthentication_token character varying(255), reauthentication_sent_at timestamp with time zone, is_sso_user boolean, deleted_at timestamp with time zone, is_anonymous boolean);
create table auth.webauthn_challenges (id uuid, user_id uuid, challenge_type text, session_data jsonb, created_at timestamp with time zone, expires_at timestamp with time zone);
create table auth.webauthn_credentials (id uuid, user_id uuid, credential_id bytea, public_key bytea, attestation_type text, aaguid uuid, sign_count bigint, transports jsonb, backup_eligible boolean, backed_up boolean, friendly_name text, created_at timestamp with time zone, updated_at timestamp with time zone, last_used_at timestamp with time zone);
create table storage.bucket_lifecycle_states (bucket_id text, generation uuid, next_run_at timestamp with time zone, claim_id uuid, claim_until timestamp with time zone, continuation jsonb, last_started_at timestamp with time zone, last_completed_at timestamp with time zone, last_success_at timestamp with time zone, last_result jsonb, failure_count integer, last_error jsonb, updated_at timestamp with time zone);
create table storage.buckets (id text primary key, name text, owner uuid, created_at timestamp with time zone, updated_at timestamp with time zone, public boolean, avif_autodetection boolean, file_size_limit bigint, allowed_mime_types text[], owner_id text, type storage.buckettype, versioning_status text, lifecycle_configuration jsonb, lifecycle_configuration_generation uuid);
create table storage.buckets_analytics (name text, type storage.buckettype, format text, created_at timestamp with time zone, updated_at timestamp with time zone, id uuid, deleted_at timestamp with time zone);
create table storage.buckets_vectors (id text, type storage.buckettype, created_at timestamp with time zone, updated_at timestamp with time zone);
create table storage.lifecycle_abandoned_artifacts (bucket_id text, key text, name text, version text, attempted_at timestamp with time zone);
create table storage.migrations (id integer, name character varying(100), hash character varying(40), executed_at timestamp without time zone);
create table storage.objects (id uuid primary key, bucket_id text, name text, owner uuid, created_at timestamp with time zone, updated_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, path_tokens text[], version text, owner_id text, user_metadata jsonb, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean);
create table storage.s3_multipart_uploads (id text, in_progress_size bigint, upload_signature text, bucket_id text, key text, version text, owner_id text, created_at timestamp with time zone, user_metadata jsonb, metadata jsonb);
create table storage.s3_multipart_uploads_parts (id uuid, upload_id text, size bigint, part_number integer, bucket_id text, key text, etag text, owner_id text, version text, created_at timestamp with time zone);
create table storage.vector_indexes (id text, name text, bucket_id text, data_type text, dimension integer, distance_metric text, metadata_configuration jsonb, created_at timestamp with time zone, updated_at timestamp with time zone);
